<template>
  <section class="master-page">
    <div class="management-head"><div><div class="eyebrow">WAREHOUSE <span>/</span> LOCATIONS</div><h1>{{ initialTab==='stock'?'货品库位库存':'仓库库位' }}</h1><p>库位余额按仓库货品记录；未建账表示该货品尚无库位库存记录。</p></div></div>
    <div class="master-toolbar">
      <el-select v-model="warehouseId" placeholder="选择仓库" style="width:220px" @change="refresh"><el-option v-for="w in warehouses" :key="w.id" :label="`${w.warehouseName} · ${w.warehouseCode}`" :value="w.id"/></el-select>
      <el-select v-model="goodsId" clearable filterable placeholder="全部仓库货品" style="width:250px" @change="refresh"><el-option v-for="g in goods" :key="g.id" :label="`${g.goodsCode} · ${g.goodsName}`" :value="g.id" style="height:64px"><div class="goods-option"><ProductReferenceImage :reference="goodsImages.get(g.id)" :label="g.goodsCode"/><span>{{ g.goodsCode }} · {{ g.goodsName }}<small>{{ g.specification||'无规格' }} · {{ g.unit }}</small></span></div></el-option></el-select>
      <LocationSelect v-model="locationId" :locations="allLocations" clearable placeholder="全部库位" style="width:220px" @change="loadStock"/>
      <el-button @click="refresh">查询</el-button>
    </div>
    <el-tabs v-model="tab" @tab-change="refresh">
      <el-tab-pane label="库位档案" name="locations" v-if="canViewLocations">
        <div class="master-toolbar"><el-input v-model="locationQuery" clearable placeholder="搜索仓库、区域、货架、层、位或编码" style="max-width:320px" @keyup.enter="loadLocations"/><el-button @click="loadLocations">筛选</el-button><el-button v-if="canManage" @click="openNode">新增区域 / 货架 / 层</el-button><el-button v-if="canManage" type="primary" @click="openLocation()">新增库位</el-button></div>
        <div class="table-card"><el-table :data="locations" v-loading="loading" empty-text="暂无库位"><el-table-column label="具体位置 / 库位编码" min-width="320"><template #default="{row}"><LocationDisplay :location="row"/></template></el-table-column><el-table-column prop="scanCode" label="扫码编码" min-width="150"/><el-table-column label="类型" width="120"><template #default="s">{{ typeLabel(s.row.locationType) }}</template></el-table-column><el-table-column label="状态" width="90"><template #default="s"><el-tag :type="s.row.status==='ACTIVE'?'success':'info'">{{ s.row.status==='ACTIVE'?'启用':'停用' }}</el-tag></template></el-table-column><el-table-column v-if="canManage" label="操作" width="180"><template #default="s"><el-button link type="primary" @click="openLocation(s.row)">编辑</el-button><el-button v-if="s.row.status==='ACTIVE'" link type="warning" @click="changeStatus(s.row,false)">停用</el-button><el-button v-else link type="success" @click="changeStatus(s.row,true)">启用</el-button></template></el-table-column></el-table></div>
      </el-tab-pane>
      <el-tab-pane label="货品位点绑定" name="assignments" v-if="canViewLocations"><div class="master-toolbar"><el-button v-if="canManage" type="primary" @click="assignmentDialog=true">绑定货品与库位</el-button><span>同一货品可绑定多个位；每仓最多一个启用的主拣货位。</span></div><div class="table-card"><el-table :data="assignments" v-loading="loading" empty-text="暂无货品位点绑定"><el-table-column label="参考图" width="76"><template #default="{row}"><ProductReferenceImage :reference="goodsImages.get(row.warehouseGoodsId)" :label="row.goodsCode" /></template></el-table-column><el-table-column prop="goodsCode" label="货品" min-width="160"/><el-table-column prop="goodsName" label="名称" min-width="160"/><el-table-column label="具体位置" min-width="300"><template #default="{row}"><LocationDisplay :location="row"/></template></el-table-column><el-table-column label="用途" width="120"><template #default="s">{{ s.row.isPrimaryPick?'主拣货位':'其他存储位' }}</template></el-table-column><el-table-column label="状态" width="100"><template #default="s">{{ s.row.status==='ACTIVE'?'启用':'停用' }}</template></el-table-column><el-table-column v-if="canManage" label="操作" width="100"><template #default="s"><el-button v-if="s.row.status==='ACTIVE'" link type="warning" @click="unbind(s.row)">解绑</el-button></template></el-table-column></el-table></div></el-tab-pane>
      <el-tab-pane label="库存分布" name="stock" v-if="canViewStock"><el-alert type="info" :closable="false" show-icon title="汇总 V2 库位余额与仓级待处理量；未建账的货品不会用 V1 SKU 库存填充。历史未知位置只显示“历史未定位”。"/><h3>仓库货品汇总</h3><div class="table-card"><el-table :data="summaries" v-loading="loading" empty-text="暂无仓库货品"><el-table-column label="参考图" width="76"><template #default="{row}"><ProductReferenceImage :reference="goodsImages.get(row.warehouseGoodsId)" :label="row.goodsCode" /></template></el-table-column><el-table-column prop="goodsCode" label="货品编码" min-width="150"/><el-table-column prop="goodsName" label="名称" min-width="160"/><el-table-column label="建账状态" width="110"><template #default="s"><el-tag :type="Number(s.row.balanceRows)?'success':'info'">{{ Number(s.row.balanceRows)?'已建账':'未建账' }}</el-tag></template></el-table-column><el-table-column label="可用" width="105"><template #default="s">{{ qty(s.row,'availableQty') }}</template></el-table-column><el-table-column label="锁定" width="105"><template #default="s">{{ qty(s.row,'lockedQty') }}</template></el-table-column><el-table-column label="仓级待入" width="105"><template #default="s">{{ locationId?'—':qty(s.row,'pendingInboundQty') }}</template></el-table-column><el-table-column label="仓级待出" width="105"><template #default="s">{{ locationId?'—':qty(s.row,'pendingOutboundQty') }}</template></el-table-column><el-table-column label="待上架" width="105"><template #default="s">{{ qty(s.row,'pendingPutawayQty') }}</template></el-table-column><el-table-column label="异常" width="105"><template #default="s">{{ qty(s.row,'abnormalQty') }}</template></el-table-column><el-table-column label="历史未定位" width="130"><template #default="s">{{ qty(s.row,'historicalUnlocatedQty') }}</template></el-table-column></el-table></div><h3>库位余额明细</h3><div class="table-card"><el-table :data="details" v-loading="loading" empty-text="尚无 V2 库位余额记录"><el-table-column label="参考图" width="76"><template #default="{row}"><ProductReferenceImage :reference="goodsImages.get(Number(row.warehouseGoodsId))" :label="String(row.goodsCode)" /></template></el-table-column><el-table-column prop="goodsCode" label="货品" min-width="145"/><el-table-column label="库位 / 历史未定位" min-width="300"><template #default="{row}"><LocationDisplay :location="row"/></template></el-table-column><el-table-column label="可用" width="105"><template #default="s">{{ s.row.availableQty }}</template></el-table-column><el-table-column prop="lockedQty" label="锁定" width="105"/><el-table-column prop="pendingPutawayQty" label="待上架" width="105"/><el-table-column prop="abnormalQty" label="异常" width="105"/><el-table-column prop="updatedAt" label="更新时间" min-width="180"/></el-table></div></el-tab-pane>
    </el-tabs>
    <el-dialog v-model="nodeDialog" title="新增区域 / 货架 / 层" width="500px"><el-form label-position="top"><el-form-item label="层级" required><el-select v-model="nodeForm.nodeKind" style="width:100%"><el-option label="区域 / 排" value="AREA"/><el-option label="货架" value="SHELF"/><el-option label="层" value="LEVEL"/></el-select></el-form-item><el-form-item v-if="nodeForm.nodeKind!=='AREA'" :label="nodeForm.nodeKind==='SHELF'?'所属区域':'所属货架'" required><el-select v-model="nodeForm.parentId" filterable style="width:100%"><el-option v-for="n in parentNodes" :key="n.id" :label="nodePath(n)" :value="n.id"/></el-select></el-form-item><el-form-item label="编码" required><el-input v-model="nodeForm.nodeCode" maxlength="40"/></el-form-item><el-form-item label="名称" required><el-input v-model="nodeForm.nodeName" maxlength="120"/></el-form-item></el-form><template #footer><el-button @click="nodeDialog=false">取消</el-button><el-button type="primary" :loading="saving" @click="saveNode">保存</el-button></template></el-dialog>
    <el-dialog v-model="locationDialog" :title="editingLocationId?'编辑库位':'新增库位'" width="600px"><el-form label-position="top"><el-form-item label="所在层" required><el-select v-model="locationForm.levelId" style="width:100%" class="location-select" popper-class="location-select-dropdown" filterable><el-option v-for="n in nodes.filter(x=>x.nodeKind==='LEVEL')" :key="n.id" :label="nodePath(n)" :value="n.id"/></el-select></el-form-item><el-row :gutter="16"><el-col :span="12"><el-form-item label="库位编码（仓库内唯一）" required><el-input v-model="locationForm.locationCode" maxlength="80"/></el-form-item></el-col><el-col :span="12"><el-form-item label="位编码" required><el-input v-model="locationForm.slotCode" maxlength="40"/></el-form-item></el-col><el-col :span="12"><el-form-item label="库位类型" required><el-select v-model="locationForm.locationType" style="width:100%"><el-option v-for="t in types" :key="t.value" :label="t.label" :value="t.value"/></el-select></el-form-item></el-col><el-col :span="12"><el-form-item label="扫码编码（仓库内唯一）"><el-input v-model="locationForm.scanCode" maxlength="100"/></el-form-item></el-col></el-row><el-form-item label="具体位置预览"><span>{{ locationPreview }}</span></el-form-item><el-form-item label="名称"><el-input v-model="locationForm.locationName" maxlength="120"/></el-form-item><el-form-item label="备注"><el-input v-model="locationForm.note" type="textarea" maxlength="1000"/></el-form-item></el-form><template #footer><el-button @click="locationDialog=false">取消</el-button><el-button type="primary" :loading="saving" @click="saveLocation">保存</el-button></template></el-dialog>
    <el-dialog v-model="assignmentDialog" title="绑定货品与库位" width="500px"><el-form label-position="top"><el-form-item label="仓库货品" required><el-select v-model="assignmentForm.warehouseGoodsId" filterable style="width:100%"><el-option v-for="g in goods.filter(x=>x.status==='ACTIVE')" :key="g.id" :label="`${g.goodsCode} · ${g.goodsName}`" :value="g.id" style="height:64px"><div class="goods-option"><ProductReferenceImage :reference="goodsImages.get(g.id)" :label="g.goodsCode"/><span>{{ g.goodsCode }} · {{ g.goodsName }}<small>{{ g.specification||'无规格' }} · {{ g.unit }}</small></span></div></el-option></el-select></el-form-item><el-form-item label="启用库位" required><LocationSelect v-model="assignmentForm.locationId" :locations="allLocations.filter(x=>x.status==='ACTIVE')" style="width:100%"/></el-form-item><el-form-item><el-checkbox v-model="assignmentForm.isPrimaryPick">设为该货品在此仓库的主拣货位</el-checkbox></el-form-item></el-form><template #footer><el-button @click="assignmentDialog=false">取消</el-button><el-button type="primary" :loading="saving" @click="saveAssignment">保存</el-button></template></el-dialog>
  </section>
</template>
<script setup lang="ts">
import LocationDisplay from '../components/LocationDisplay.vue'
import LocationSelect from '../components/LocationSelect.vue'
import { locationLabel, locationTypeName } from '../utils/location'
import { computed,onMounted,reactive,ref,watch } from 'vue'
import { ElMessage,ElMessageBox } from 'element-plus'
import { useRoute } from 'vue-router'
import { api,type AuthUser } from '../api'
import ProductReferenceImage from '../components/ProductReferenceImage.vue'
import { useProductReferences } from '../utils/productReferences'
import { useWarehouseRefresh } from '../utils/warehouseUpdates'
type Warehouse={id:number;warehouseCode:string;warehouseName:string;status:string}
type Good={id:number;goodsCode:string;goodsName:string;specification?:string;unit:string;status:string}
type Node={id:number;parentId:number|null;nodeKind:string;nodeCode:string;nodeName:string}
type Location={locationPath?:string;locationTypeName?:string;id:number;warehouseId:number;levelId:number;locationCode:string;slotCode:string;locationName:string|null;scanCode:string|null;locationType:string;status:string;note:string|null;areaCode:string;shelfCode:string;levelCode:string}
type Assignment={locationPath?:string;id:number;warehouseGoodsId:number;goodsCode:string;goodsName:string;locationCode:string;status:string;isPrimaryPick:boolean}
type Summary={warehouseGoodsId:number;balanceRows:number;pendingBalanceId:number|null;availableQty:number;lockedQty:number;pendingPutawayQty:number;pendingInboundQty:number;pendingOutboundQty:number;abnormalQty:number;historicalUnlocatedQty:number;goodsCode:string;goodsName:string}
const props=defineProps<{user?:AuthUser;initialTab?:string}>()
const route=useRoute()
const canManage=computed(()=>props.user?.permissions.includes('button.locations.manage')??false),canViewLocations=computed(()=>props.user?.permissions.includes('warehouse.locations.view')??false),canViewStock=computed(()=>props.user?.permissions.includes('warehouse.location_stock.view')??false)
const tab=ref(props.initialTab||'locations'),warehouses=ref<Warehouse[]>([]),goods=ref<Good[]>([]),nodes=ref<Node[]>([]),locations=ref<Location[]>([]),allLocations=ref<Location[]>([]),assignments=ref<Assignment[]>([]),summaries=ref<Summary[]>([]),details=ref<Record<string,unknown>[]>([])
const goodsImages=useProductReferences('WAREHOUSE_GOODS')
const warehouseId=ref<number>(),goodsId=ref<number>(),locationId=ref<number>(),locationQuery=ref(''),loading=ref(false),saving=ref(false),nodeDialog=ref(false),locationDialog=ref(false),assignmentDialog=ref(false),editingLocationId=ref<number>()
const nodeForm=reactive({nodeKind:'AREA',parentId:undefined as number|undefined,nodeCode:'',nodeName:''}),locationForm=reactive({levelId:undefined as number|undefined,locationCode:'',slotCode:'',locationName:'',scanCode:'',locationType:'STORAGE',note:''}),assignmentForm=reactive({warehouseGoodsId:undefined as number|undefined,locationId:undefined as number|undefined,isPrimaryPick:false})
const types=[{value:'STORAGE',label:'正式存储位'},{value:'PRIMARY_PICK',label:'主拣货位'},{value:'PENDING_PUTAWAY',label:'待上架位'},{value:'TEMPORARY',label:'暂存位'},{value:'QUARANTINE',label:'异常 / 待检位'}]
const parentNodes=computed(()=>nodes.value.filter(n=>n.nodeKind===(nodeForm.nodeKind==='SHELF'?'AREA':'SHELF')))
const typeLabel=locationTypeName
const qty=(row:Summary,key:keyof Summary)=>(key==='pendingInboundQty'||key==='pendingOutboundQty'?row.pendingBalanceId:Number(row.balanceRows))?Number(row[key]).toFixed(4):'未建账'
const error=(e:unknown)=>ElMessage.error(e instanceof Error?e.message:'操作失败')
onMounted(async()=>{try{warehouses.value=(await api<{warehouses:Warehouse[]}>('/api/warehouse-locations/warehouses')).warehouses;warehouseId.value=warehouses.value.find(w=>w.status==='ACTIVE')?.id;goods.value=(await api<{goods:Good[]}>('/api/warehouse-locations/goods')).goods;void goodsImages.load(goods.value.map(g=>g.id));const selected=Number(route.query.goodsId);if(Number.isSafeInteger(selected)&&goods.value.some(g=>g.id===selected))goodsId.value=selected;await refresh()}catch(e){error(e)}})
watch(canViewStock,enabled=>{if(enabled&&warehouseId.value)loadStock()})
watch(canViewLocations,enabled=>{if(enabled&&warehouseId.value)refresh()})
useWarehouseRefresh(async()=>{
  if(!warehouseId.value||loading.value||saving.value)return
  if(tab.value==='assignments'&&canViewLocations.value){
    const wh=warehouseId.value,good=goodsId.value
    const result=await api<{assignments:Assignment[]}>(`/api/warehouse-locations/assignments?warehouseId=${wh}${good?`&goodsId=${good}`:''}`)
    if(wh===warehouseId.value&&good===goodsId.value)assignments.value=result.assignments
  }else if(tab.value==='stock'&&canViewStock.value)await loadStock()
})
async function refresh(){if(!warehouseId.value)return;loading.value=true;try{const wh=warehouseId.value;[nodes.value,locations.value,allLocations.value,assignments.value]=await Promise.all([api<{nodes:Node[]}>(`/api/warehouse-locations/nodes?warehouseId=${wh}`).then(x=>x.nodes),api<{locations:Location[]}>(`/api/warehouse-locations?warehouseId=${wh}${goodsId.value?`&goodsId=${goodsId.value}`:''}${locationQuery.value?`&q=${encodeURIComponent(locationQuery.value)}`:''}`).then(x=>x.locations),api<{locations:Location[]}>(`/api/warehouse-locations?warehouseId=${wh}`).then(x=>x.locations),canViewLocations.value?api<{assignments:Assignment[]}>(`/api/warehouse-locations/assignments?warehouseId=${wh}${goodsId.value?`&goodsId=${goodsId.value}`:''}`).then(x=>x.assignments):Promise.resolve([] as Assignment[])]);if(locationId.value&&!allLocations.value.some(x=>x.id===locationId.value))locationId.value=undefined;if(canViewStock.value)await loadStock()}catch(e){error(e)}finally{loading.value=false}}
async function loadLocations(){if(!warehouseId.value)return;try{locations.value=(await api<{locations:Location[]}>(`/api/warehouse-locations?warehouseId=${warehouseId.value}${goodsId.value?`&goodsId=${goodsId.value}`:''}${locationQuery.value?`&q=${encodeURIComponent(locationQuery.value)}`:''}`)).locations}catch(e){error(e)}}
async function loadStock(){if(!warehouseId.value||!canViewStock.value)return;const q=new URLSearchParams({warehouseId:String(warehouseId.value)});if(goodsId.value)q.set('goodsId',String(goodsId.value));if(locationId.value)q.set('locationId',String(locationId.value));try{const [s,d]=await Promise.all([api<{items:Summary[]}>(`/api/warehouse-locations/stock-summary?${q}`),api<{items:Record<string,unknown>[]}>(`/api/warehouse-locations/stock-details?${q}`)]);summaries.value=s.items;details.value=d.items}catch(e){error(e)}}
function openNode(){Object.assign(nodeForm,{nodeKind:'AREA',parentId:undefined,nodeCode:'',nodeName:''});nodeDialog.value=true}
function openLocation(row?:Location){editingLocationId.value=row?.id;Object.assign(locationForm,{levelId:row?.levelId,locationCode:row?.locationCode||'',slotCode:row?.slotCode||'',locationName:row?.locationName||'',scanCode:row?.scanCode||'',locationType:row?.locationType||'STORAGE',note:row?.note||''});locationDialog.value=true}
function nodePath(n:Node){const chain:string[]=[];let current:Node|undefined=n;const seen=new Set<number>();while(current&&!seen.has(current.id)){seen.add(current.id);chain.unshift(current.nodeName||current.nodeCode);current=nodes.value.find(x=>x.id===current?.parentId)}return [warehouses.value.find(w=>w.id===warehouseId.value)?.warehouseName,...chain].filter(Boolean).join(' / ')}
const locationPreview=computed(()=>{const level=nodes.value.find(n=>n.id===locationForm.levelId);return level?`${nodePath(level)} / ${locationForm.slotCode?locationForm.slotCode+'位':'请选择位编码'}`:'请选择所在层'})
async function saveNode(){if(!warehouseId.value||!nodeForm.nodeCode.trim()||!nodeForm.nodeName.trim()||(nodeForm.nodeKind!=='AREA'&&!nodeForm.parentId)){ElMessage.warning('请填写层级与父级');return}saving.value=true;try{await api('/api/warehouse-locations/nodes',{method:'POST',body:JSON.stringify({...nodeForm,warehouseId:warehouseId.value,parentId:nodeForm.nodeKind==='AREA'?null:nodeForm.parentId})});nodeDialog.value=false;await refresh();ElMessage.success('层级已创建')}catch(e){error(e)}finally{saving.value=false}}
async function saveLocation(){if(!warehouseId.value||!locationForm.levelId||!locationForm.locationCode.trim()||!locationForm.slotCode.trim()){ElMessage.warning('请填写层、库位编码和位编码');return}saving.value=true;try{await api(editingLocationId.value?`/api/warehouse-locations/${editingLocationId.value}`:'/api/warehouse-locations',{method:editingLocationId.value?'PUT':'POST',body:JSON.stringify({...locationForm,warehouseId:warehouseId.value})});locationDialog.value=false;await refresh();ElMessage.success('库位已保存')}catch(e){error(e)}finally{saving.value=false}}
async function changeStatus(row:Location,activate:boolean){try{if(!activate)await ElMessageBox.confirm(`停用库位 ${locationLabel(row)}？有库存、任务或货品绑定时会拒绝。`,'停用库位',{type:'warning'});await api(`/api/warehouse-locations/${row.id}/${activate?'activate':'deactivate'}`,{method:'POST'});await refresh();ElMessage.success(activate?'库位已启用':'库位已停用')}catch(e){if(e!=='cancel'&&e!=='close')error(e)}}
async function saveAssignment(){if(!warehouseId.value||!assignmentForm.warehouseGoodsId||!assignmentForm.locationId){ElMessage.warning('请选择货品和库位');return}saving.value=true;try{await api('/api/warehouse-locations/assignments',{method:'POST',body:JSON.stringify({...assignmentForm,warehouseId:warehouseId.value})});assignmentDialog.value=false;await refresh();ElMessage.success('货品库位已绑定')}catch(e){error(e)}finally{saving.value=false}}
async function unbind(row:Assignment){try{await ElMessageBox.confirm(`解绑 ${row.goodsCode} 与 ${locationLabel(row)}？`,'解绑货品库位',{type:'warning'});await api(`/api/warehouse-locations/assignments/${row.id}/deactivate`,{method:'POST'});await refresh();ElMessage.success('绑定已停用')}catch(e){if(e!=='cancel'&&e!=='close')error(e)}}
</script>
<style scoped>
.goods-option{display:flex;align-items:center;gap:10px}.goods-option small{display:block;color:#909399}
</style>
